import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const STATUSES = ['신청', '승인', '승인취소'];

function invalid(message: string): ApiError {
  return new ApiError(422, 'INSPECTION_PLAN_INVALID', message);
}

function readPlan(data: Record<string, unknown>) {
  const inspectionType = data['inspectionType'];
  const startDate = data['startDate'];
  const endDate = data['endDate'];
  const targetScope = data['targetScope'];
  const managerId = data['managerId'];
  if (typeof inspectionType !== 'string' || inspectionType.trim() === '' || inspectionType.length > 50) {
    throw invalid('실사 유형을 확인해 주세요.');
  }
  if (typeof startDate !== 'string' || !DATE_PATTERN.test(startDate)) {
    throw invalid('실사 시작일을 확인해 주세요.');
  }
  if (typeof endDate !== 'string' || !DATE_PATTERN.test(endDate)) {
    throw invalid('실사 종료일을 확인해 주세요.');
  }
  const managerText = String(managerId ?? '');
  if (!/^\d+$/.test(managerText)) {
    throw invalid('실사 담당자를 확인해 주세요.');
  }
  if (targetScope !== undefined && targetScope !== null && typeof targetScope !== 'string') {
    throw invalid('실사 대상 범위를 확인해 주세요.');
  }
  return {
    inspectionType: inspectionType.trim(),
    startDate,
    endDate,
    targetScope: typeof targetScope === 'string' && targetScope !== '' ? targetScope : null,
    managerId: managerText,
  };
}

async function checkPlanValues(db: any, p: { startDate: string; endDate: string; managerId: string }) {
  const dates = await db.query(
    'SELECT (CAST(:startDate AS date) > CAST(:endDate AS date)) AS "bad"',
    { startDate: p.startDate, endDate: p.endDate },
  );
  if (dates[0] && dates[0].bad) {
    throw invalid('실사 시작일은 종료일보다 늦을 수 없습니다.');
  }
  const managers = await db.query(
    'SELECT employee_id FROM employee WHERE employee_id = CAST(:managerId AS bigint)',
    { managerId: p.managerId },
  );
  if (managers.length === 0) {
    throw invalid('실사 담당자를 찾을 수 없습니다.');
  }
}

function planId(req: Request): string {
  const id = req.params['assetInspectionPlanId'];
  if (typeof id !== 'string' || !/^\d+$/.test(id)) {
    throw new ApiError(404, 'INSPECTION_PLAN_NOT_FOUND', '실사계획을 찾을 수 없습니다.');
  }
  return id;
}

@Controller('api/v1')
export class FnSfr02505Controller {
  @Post('/asset-inspection-plans')
  @HttpCode(200)
  async createAssetInspectionPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const data = checks.inputOf(req.body);
    const p = readPlan(data);
    return transaction(async (db) => {
      await checkPlanValues(db, p);
      const rows = await db.query(
        `INSERT INTO asset_inspection_plan
           (inspection_type, start_date, end_date, target_scope, manager_id, approval_status, created_at, updated_at)
         VALUES
           (:inspectionType, CAST(:startDate AS date), CAST(:endDate AS date), :targetScope, CAST(:managerId AS bigint), '신청', now(), now())
         RETURNING asset_inspection_plan_id AS "assetInspectionPlanId", approval_status AS "approvalStatus"`,
        p,
      );
      return rows[0];
    });
  }

  @Get('/asset-inspection-plans')
  async listAssetInspectionPlans(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자', '임직원');
    const query = checks.queryOf(req.query);
    const pageNum = Number(query['page'] ?? 0);
    const sizeNum = Number(query['size'] ?? DEFAULT_SIZE);
    if (!Number.isInteger(pageNum) || pageNum < 0 || !Number.isInteger(sizeNum) || sizeNum < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeNum, MAX_SIZE);
    const inspectionType = typeof query['inspectionType'] === 'string' && query['inspectionType'] !== '' ? query['inspectionType'] : null;
    const approvalStatus = typeof query['approvalStatus'] === 'string' && query['approvalStatus'] !== '' ? query['approvalStatus'] : null;
    if (approvalStatus !== null && !STATUSES.includes(approvalStatus as string)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '승인 상태 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const params = { inspectionType, approvalStatus };
      const where = `WHERE (CAST(:inspectionType AS text) IS NULL OR inspection_type = CAST(:inspectionType AS text))
          AND (CAST(:approvalStatus AS text) IS NULL OR approval_status = CAST(:approvalStatus AS text))`;
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM asset_inspection_plan ${'$'}{WHERE}`.replace('${'+'$'+'}{WHERE}', where),
        params,
      );
      const items = await db.query(
        `SELECT asset_inspection_plan_id AS "assetInspectionPlanId",
                inspection_type AS "inspectionType",
                to_char(start_date, 'YYYY-MM-DD') AS "startDate",
                to_char(end_date, 'YYYY-MM-DD') AS "endDate",
                target_scope AS "targetScope",
                manager_id AS "managerId",
                approval_status AS "approvalStatus"
           FROM asset_inspection_plan
           ` + where + `
          ORDER BY asset_inspection_plan_id DESC
          LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)`,
        { ...params, limit: size, offset: pageNum * size },
      );
      return { items, page: pageNum, size, total: Number(counts[0].total) };
    });
  }

  @Put('/asset-inspection-plans/:assetInspectionPlanId')
  async updateAssetInspectionPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const id = planId(req);
    const data = checks.inputOf(req.body);
    const p = readPlan(data);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM asset_inspection_plan WHERE asset_inspection_plan_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'INSPECTION_PLAN_NOT_FOUND', '실사계획을 찾을 수 없습니다.');
      }
      if (found[0].approvalStatus === '승인') {
        throw new ApiError(409, 'INSPECTION_PLAN_APPROVED', '승인된 계획은 승인취소 후에 수정할 수 있습니다.');
      }
      await checkPlanValues(db, p);
      const rows = await db.query(
        `UPDATE asset_inspection_plan
            SET inspection_type = :inspectionType,
                start_date = CAST(:startDate AS date),
                end_date = CAST(:endDate AS date),
                target_scope = :targetScope,
                manager_id = CAST(:managerId AS bigint),
                updated_at = now()
          WHERE asset_inspection_plan_id = CAST(:id AS bigint)
          RETURNING asset_inspection_plan_id AS "assetInspectionPlanId"`,
        { ...p, id },
      );
      return rows[0];
    });
  }

  @Post('/asset-inspection-plans/:assetInspectionPlanId/approve')
  @HttpCode(200)
  async approveAssetInspectionPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자', '임직원');
    const id = planId(req);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM asset_inspection_plan WHERE asset_inspection_plan_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'INSPECTION_PLAN_NOT_FOUND', '실사계획을 찾을 수 없습니다.');
      }
      if (found[0].approvalStatus !== '신청') {
        throw new ApiError(409, 'INSPECTION_PLAN_STATUS_CONFLICT', '신청 상태인 계획만 승인할 수 있습니다.');
      }
      const rows = await db.query(
        `UPDATE asset_inspection_plan
            SET approval_status = '승인', updated_at = now()
          WHERE asset_inspection_plan_id = CAST(:id AS bigint)
          RETURNING approval_status AS "approvalStatus"`,
        { id },
      );
      return rows[0];
    });
  }

  @Post('/asset-inspection-plans/:assetInspectionPlanId/cancel-approval')
  @HttpCode(200)
  async cancelApprovalAssetInspectionPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자', '임직원');
    const id = planId(req);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM asset_inspection_plan WHERE asset_inspection_plan_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'INSPECTION_PLAN_NOT_FOUND', '실사계획을 찾을 수 없습니다.');
      }
      if (found[0].approvalStatus !== '승인') {
        throw new ApiError(409, 'INSPECTION_PLAN_STATUS_CONFLICT', '승인 상태인 계획만 승인취소할 수 있습니다.');
      }
      // 가정: 진행 중인 실사를 담는 테이블이 schema.sql에 없어 INSPECTION_IN_PROGRESS 검사는 구현하지 못했다.
      const rows = await db.query(
        `UPDATE asset_inspection_plan
            SET approval_status = '승인취소', updated_at = now()
          WHERE asset_inspection_plan_id = CAST(:id AS bigint)
          RETURNING approval_status AS "approvalStatus"`,
        { id },
      );
      return rows[0];
    });
  }
}

