import { useState } from 'react';
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles,
  Form, Field, TextInput, DateInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['승인', '승인'],
  ['승인취소', '승인취소'],
];

const EMPTY_FORM: Row = {
  inspectionType: '',
  startDate: '',
  endDate: '',
  targetScope: '',
  managerId: '',
};

export default function FnSfr02505Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [typeFilter, setTypeFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [applied, setApplied] = useState({ type: '', status: '' });
  const [detail, setDetail] = useState<Row | null>(null);
  const [editing, setEditing] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [form, setForm] = useState<Row>(EMPTY_FORM);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/asset-inspection-plans', role, undefined, {
      page,
      size: 20,
      inspectionType: applied.type,
      approvalStatus: applied.status,
    }),
    [page, applied.type, applied.status, role],
  );
  const rows = data ? data.items : [];
  const waiting = rows.filter((r) => r['approvalStatus'] === '신청');

  function setField(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  function openCreate() {
    setForm(EMPTY_FORM);
    setEditing(null);
    setCreating(true);
  }

  function openEdit(row: Row) {
    setForm({
      inspectionType: row['inspectionType'],
      startDate: row['startDate'],
      endDate: row['endDate'],
      targetScope: row['targetScope'] ?? '',
      managerId: row['managerId'],
    });
    setEditing(row);
    setDetail(null);
  }

  function closeForm() {
    setCreating(false);
    setEditing(null);
  }

  function checkForm() {
    if (!String(form['inspectionType'] ?? '').trim()) throw new Error('실사 유형을 입력해 주세요.');
    if (!form['startDate']) throw new Error('실사 시작일을 입력해 주세요.');
    if (!form['endDate']) throw new Error('실사 종료일을 입력해 주세요.');
    if (!form['managerId']) throw new Error('실사 담당자를 선택해 주세요.');
    if (String(form['startDate']) > String(form['endDate'])) {
      throw new Error('실사 시작일은 종료일보다 늦을 수 없습니다.');
    }
  }

  async function submitForm() {
    checkForm();
    const body: Row = {
      inspectionType: form['inspectionType'],
      startDate: form['startDate'],
      endDate: form['endDate'],
      targetScope: form['targetScope'],
      managerId: form['managerId'],
    };
    if (editing) {
      await call('PUT', `/asset-inspection-plans/${editing['assetInspectionPlanId']}`, role, body);
      notify('실사계획을 수정했습니다.');
    } else {
      await call('POST', '/asset-inspection-plans', role, body);
      notify('실사계획을 작성했습니다.');
    }
    closeForm();
    reload();
  }

  async function approve(row: Row) {
    await call('POST', `/asset-inspection-plans/${row['assetInspectionPlanId']}/approve`, role);
    notify('실사계획을 승인했습니다.');
    setDetail(null);
    reload();
  }

  async function cancelApproval(row: Row) {
    await call('POST', `/asset-inspection-plans/${row['assetInspectionPlanId']}/cancel-approval`, role);
    notify('실사계획 승인을 취소했습니다.');
    setDetail(null);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>전체 계획</h2>
        <Tiles items={[['조회 건수', data ? data.total : 0]]} />
      </section>
      <section className="box span-4">
        <h2>승인 대기</h2>
        <Tiles items={[['신청 상태', waiting.length]]} />
      </section>
      <section className="box span-4">
        <h2>승인 완료</h2>
        <Tiles items={[['승인 상태', rows.filter((r) => r['approvalStatus'] === '승인').length]]} />
      </section>
      <section className="box span-8">
        <h2>실사계획</h2>
        <Filters
          onSearch={() => { setPage(0); setApplied({ type: typeFilter, status: statusFilter }); }}
          onReset={() => { setTypeFilter(''); setStatusFilter(''); setPage(0); setApplied({ type: '', status: '' }); }}
        >
          <Field label="실사 유형">
            <TextInput value={typeFilter} onChange={setTypeFilter} />
          </Field>
          <Field label="승인 상태">
            <Select value={statusFilter} onChange={setStatusFilter} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openCreate}>실사계획 작성</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={rows}
          onRowClick={(row) => setDetail(row)}
          empty="실사계획이 없습니다."
          columns={[
            { key: 'inspectionType', label: '실사 유형' },
            { key: 'startDate', label: '실사 시작일', render: (r) => <DateText value={r['startDate']} /> },
            { key: 'endDate', label: '실사 종료일', render: (r) => <DateText value={r['endDate']} /> },
            { key: 'managerId', label: '실사 담당자', render: (r) => <RefName table="employee" role={role} value={r['managerId']} /> },
            { key: 'approvalStatus', label: '승인 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
          ]}
        />
        <Pager page={page} size={20} total={data ? data.total : 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable
          rows={waiting}
          onRowClick={(row) => setDetail(row)}
          empty="승인 대기 계획이 없습니다."
          columns={[
            { key: 'inspectionType', label: '실사 유형' },
            { key: 'startDate', label: '실사 시작일', render: (r) => <DateText value={r['startDate']} /> },
          ]}
        />
      </section>
      {detail ? (
        <Drawer title="실사계획 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['실사 유형', String(detail['inspectionType'] ?? '')],
              ['실사 시작일', <DateText value={detail['startDate']} />],
              ['실사 종료일', <DateText value={detail['endDate']} />],
              ['실사 대상 범위', String(detail['targetScope'] ?? '')],
              ['실사 담당자', <RefName table="employee" role={role} value={detail['managerId']} />],
              ['승인 상태', <Badge value={detail['approvalStatus']} />],
            ]}
          />
          {detail['approvalStatus'] !== '승인' ? (
            <button type="button" onClick={() => openEdit(detail)}>수정</button>
          ) : null}
          {detail['approvalStatus'] === '신청' ? (
            <Form submit="승인" onSubmit={() => approve(detail)} note="이 실사계획을 승인합니다." />
          ) : null}
          {detail['approvalStatus'] === '승인' ? (
            <Form submit="승인취소" danger onSubmit={() => cancelApproval(detail)} note="승인을 취소하면 수정할 수 있는 상태가 됩니다." />
          ) : null}
        </Drawer>
      ) : null}
      {creating || editing ? (
        <Drawer title={editing ? '실사계획 수정' : '실사계획 작성'} onClose={closeForm}>
          <Form submit={editing ? '수정' : '작성'} onSubmit={submitForm}>
            <Field label="실사 유형" required>
              <TextInput value={form['inspectionType']} onChange={(v) => setField('inspectionType', v)} />
            </Field>
            <Field label="실사 시작일" required>
              <DateInput value={form['startDate']} onChange={(v) => setField('startDate', v)} />
            </Field>
            <Field label="실사 종료일" required>
              <DateInput value={form['endDate']} onChange={(v) => setField('endDate', v)} />
            </Field>
            <Field label="실사 대상 범위" wide>
              <TextInput multiline value={form['targetScope']} onChange={(v) => setField('targetScope', v)} />
            </Field>
            <Field label="실사 담당자" required>
              <LookupSelect table="employee" role={role} value={form['managerId']} onChange={(v) => setField('managerId', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
